import {offers} from './lib/story.js';
import {scenarios} from './lib/scenarios.js';
import {clone,createWorld,advance,inject,editActor,forkWorld,importWorld,observe,queueAction,availability,validateScenario,negotiate} from './lib/engine.js';
import {generateScenario,modelDecisions} from './lib/model.js';
const $=s=>document.querySelector(s);const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let introIndex=0;
let world=null,draft=null,selected='startup',screen='home',tab='world',actorId=null,view='director',busy=false,auto=false,timer=null,historyIndex=null,config=null,serverConfig=null;
try{const saved=localStorage.getItem('worldplay-save');if(saved)world=importWorld(JSON.parse(saved));}catch{localStorage.removeItem('worldplay-save');}
const logo=`<span class="logo-mark">✳</span><b>worldplay<span class="logo-dot">.</span></b>`;
function notify(s){$('#toast').textContent=s;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function persist(){try{localStorage.setItem('worldplay-save',JSON.stringify(world));}catch{notify('浏览器存储空间不足，请导出存档。');}}
function stop(){auto=false;clearTimeout(timer);}
function header(){return `<header><button class="brand" data-do="home" aria-label="Worldplay 首页">${logo}</button><span class="header-divider"></span><span class="header-label">多角色世界沙盘</span><nav><button class="quiet" data-do="guide">使用指南 ↗</button><button class="mode-button" data-do="settings"><i class="dot ${config?'green':''}"></i>${config?'模型已连接':'规则演示模式'} <span>⌄</span></button></nav></header>`;}
function footer(){return `<footer><span>WORLDPLAY LAB <small> / </small> v0.1</span><span>每一次选择，都让世界走向不同的地方。</span><button data-do="guide">CLI & Agent 接入 ↗</button></footer>`;}
function illustration(id){if(id==='startup')return `<svg viewBox="0 0 340 130" aria-hidden="true"><g stroke="currentColor" fill="none" stroke-width="1.4"><path d="M35 105H307M55 100V57h46v43M115 100V38h46v62M175 100V70h46v30M235 100V18h46v82"/><path d="m45 42 50-15 54 14 51-28 59 4" stroke-dasharray="4 4"/><circle cx="95" cy="27" r="5" fill="currentColor"/><circle cx="200" cy="13" r="5" fill="currentColor"/></g><text x="285" y="35" fill="currentColor" font-size="12">↗</text></svg>`;if(id==='succession')return `<svg viewBox="0 0 340 130" aria-hidden="true"><g fill="none" stroke="currentColor" stroke-width="1.4"><path d="M45 102h250M75 102V62h34v40m20 0V46h34v56m20 0V62h34v40m20 0V35h34v67M60 36l90-23 120 7"/><circle cx="92" cy="43" r="9"/><circle cx="146" cy="28" r="9"/><circle cx="200" cy="44" r="9"/><path d="m247 25-11-13 11 4 9-12 8 12 11-4-11 13z" fill="currentColor"/></g></svg>`;return `<svg viewBox="0 0 340 130" aria-hidden="true"><g fill="none" stroke="currentColor" stroke-width="1.4"><ellipse cx="170" cy="66" rx="113" ry="37" transform="rotate(-12 170 66)" stroke-dasharray="3 6"/><circle cx="170" cy="66" r="37"/><path d="m155 81 11-41 26 30-15-1-7 16-5-11z"/><path d="m81 23 0 10m-5-5h10m161 64v12m-6-6h12M268 31v8m-4-4h8"/><circle cx="56" cy="79" r="4" fill="currentColor"/><circle cx="256" cy="41" r="4" fill="currentColor"/></g></svg>`;}
function home(){return `${header()}<main class="home"><div class="eyebrow"><span class="tiny-line"></span> 一个念头，无数种可能</div><h1>世界，由你<span>开局。</span></h1><p class="lead">一句话，一个角色，或一段故事。<br>让世界运转起来，随时加入，改变它的走向。</p><form id="create-form" class="prompt-box"><textarea id="world-prompt" aria-label="描述你的世界" placeholder="如果一家 AI 创业公司只剩 30 天现金，四位各有打算的合伙人会怎么做？" maxlength="6000"></textarea><div class="prompt-bottom"><span>✧ ${config?'AI 将补全角色、规则和初始事件':'先选一个世界试玩，或连接模型自由创建'}</span><button class="primary" type="submit" ${busy?'disabled':''}>${busy?'正在构建世界…':'构建世界'} <span>↗</span></button></div></form><div class="section-heading"><h2>从第一个故事开始</h2><label class="skip-preference"><input type="checkbox" id="skip-all-intros" ${skipIntros()?'checked':''}> 所有 Demo 跳过开场引导</label></div><div class="scenario-grid">${scenarios.map((s,i)=>`<button class="scenario-card" data-scenario="${s.id}" style="--accent:${s.accent}"><div class="card-top"><span>0${i+1} / ${s.genre}</span><span>↗</span></div><div class="illustration">${illustration(s.id)}</div><h3>${s.title}</h3><p>${s.description}</p><div class="card-bottom"><span>${s.actors.length} 位角色 <em>·</em> ${s.maxRounds} 轮演化</span><span>进入世界 →</span></div></button>`).join('')}</div>${world?`<button class="resume" data-do="resume"><span>◷ 继续上次的世界 <b>${esc(world.scenario.title)}</b></span><span>第 ${world.round} 轮 →</span></button>`:''}<div class="steps"><span><b>01</b> 定义局面</span><i>→</i><span><b>02</b> 观察演化</span><i>→</i><span><b>03</b> 改变走向</span></div></main>${footer()}`;}
function setup(){const s=draft;return `${header()}<main class="setup"><button class="back" data-do="home">← 返回所有世界</button><div class="eyebrow">WORLD SETUP / 世界开局</div><h1>${esc(s.title)}</h1><p class="lead">这是故事的起点。你可以修改任何设定，再让世界运转。</p><div class="setup-grid"><section class="panel setup-fields"><label>演化主题<textarea id="theme">${esc(s.theme)}</textarea></label><label>初始事件<textarea id="opening" rows="4">${esc(s.opening)}</textarea></label><div class="section-heading"><h2>资源与规则</h2><button class="text-button" data-do="json">编辑场景 JSON ↗</button></div><div class="resource-inputs">${s.metrics.map(m=>`<label>${esc(m.label)}<div><input type="number" data-metric="${m.id}" min="${m.min}" max="${m.max}" value="${m.value}"><span>${esc(m.unit)}</span></div></label>`).join('')}</div><div class="rule-list">${s.actions.map(a=>`<div><b>${esc(a.label)}</b><span>${Object.entries(a.requires).map(([k,v])=>`${esc(s.metrics.find(m=>m.id===k).label)} ≥ ${v}`).join(' · ')||'满足资源条件即可执行'}</span></div>`).join('')}</div><label class="round-input">运行上限 <input id="max-rounds" type="number" min="2" max="30" value="${s.maxRounds}"> 轮</label></section><section><div class="section-heading"><h2>局中人</h2><span>${s.actors.length} 个独立目标</span></div>${s.actors.map(a=>`<button class="setup-actor" data-edit-draft="${a.id}"><span class="avatar" style="--actor:${a.color}">${esc(a.name[0])}</span><span><b>${esc(a.name)} <small>${esc(a.role)}</small></b><p>${esc(a.goal)}</p></span><span class="edit-glyph">↗</span></button>`).join('')}<div class="setup-note">✳ <span>${s.id==='startup'?'你将扮演 CEO，从危机发生前开始决策。':'初次运行两轮后自动暂停。'}<br>你可以随时修改角色、加入事件，或接管行动。</span></div><button class="primary start-button" data-do="start">让世界运转 <span>→</span></button><p class="small-note">${config?'使用已连接的模型独立决策。':'当前为规则演示：行动由预设策略选择，可验证状态与交互。'}</p></section></div></main>${footer()}`;}
function current(){return historyIndex===null?world:world.snapshots[historyIndex];}
function visibleEvents(w){return view==='director'?w.events:w.events.filter(e=>e.visibility==='public'||e.actorId===view||e.target===view);}
function graph(w){const actors=w.actors,n=actors.length,points=actors.map((_,i)=>({x:50+35*Math.cos(-Math.PI/2+i*2*Math.PI/n),y:50+34*Math.sin(-Math.PI/2+i*2*Math.PI/n)}));return `<div class="world-map"><div class="map-caption">RELATIONSHIP MAP <span>关系随互动积累</span></div><svg class="connections" viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true">${w.relations.map(r=>{const a=points[actors.findIndex(a=>a.id===r.from)],b=points[actors.findIndex(a=>a.id===r.to)];return `<line x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}" stroke="${r.value>55?'#bc7957':'#d7d2c8'}" stroke-width="${r.value>55?.38:.22}" stroke-dasharray="${r.value>55?'0':'1 1'}"/>`;}).join('')}</svg><div class="map-core"><span>✳</span><b>${esc(w.scenario.center)}</b><small>${w.round===0?'等待第一次行动':`第 ${w.round} 轮 · ${w.result?'已结束':'世界演化中'}`}</small></div>${actors.map((a,i)=>`<button class="map-actor ${actorId===a.id?'selected':''}" style="left:${points[i].x}%;top:${points[i].y}%;--actor:${a.color}" data-actor="${a.id}"><span class="avatar">${esc(a.name[0])}</span><b>${esc(a.name)}</b><small>${esc(a.role)}</small><em>${esc(a.lastAction)}</em></button>`).join('')}<div class="map-legend"><i></i> 初始关系 <i class="active"></i> 互动增强 <span>点击角色查看详情 ↗</span></div></div>`;}
function eventsHtml(w){const items=visibleEvents(w).filter(e=>tab!=='actions'||['action','world','intervention','ending'].includes(e.type));return items.slice().reverse().map(e=>`<article class="event ${e.type}"><div class="event-marker">${e.type==='message'?'“':e.type==='intervention'?'✧':e.type==='world'?'◷':e.type==='ending'?'◆':'↗'}</div><div><div class="event-heading"><b>${esc(e.title)}</b><small>R${String(e.round).padStart(2,'0')}${e.visibility==='private'?' · 私信':''}</small></div><p>${esc(e.text)}</p>${e.changes?`<div class="change-tags">${Object.entries(e.changes).filter(([,v])=>v).map(([k,v])=>`<span class="${v>0?'positive':'negative'}">${esc(w.scenario.metrics.find(m=>m.id===k)?.label)} ${v>0?'+':''}${v}</span>`).join('')}</div>`:''}</div></article>`).join('');}
function actorPanel(w){const a=w.actors.find(a=>a.id===actorId);if(!a)return '';const privateAllowed=view==='director'||view===a.id;return `<section class="actor-detail"><div class="section-heading"><h2>${esc(a.name)} <small>${esc(a.role)}</small></h2>${historyIndex===null&&view==='director'?`<button class="text-button" data-edit="${a.id}">编辑角色 ↗</button>`:''}</div><p><span class="field-label">当前目标</span>${privateAllowed?esc(a.goal):'该角色的私人目标不可见。'}</p>${privateAllowed?`<p><span class="field-label">性格</span>${esc(a.personality)}</p><p class="secret"><span class="field-label">私密信息</span>${esc(a.secret)}</p>`:''}<div class="relation-list">${w.relations.filter(r=>r.from===a.id||r.to===a.id).map(r=>`<span>${esc(w.actors.find(x=>x.id===(r.from===a.id?r.to:r.from)).name)} <b>${r.value}</b></span>`).join('')}</div>${historyIndex===null&&!world.result?`<button class="secondary" data-control="${a.id}">接管本轮行动 →</button>`:''}</section>`;}
function workspace(){const w=current();return `${header()}<div class="workspace"><aside class="sidebar"><div class="sidebar-label">我的世界</div>${scenarios.map(s=>`<button class="world-link ${w.scenario.id===s.id?'active':''}" data-scenario="${s.id}"><span>${s.icon}</span>${s.title}</button>`).join('')}<button class="new-world" data-do="home">＋ 创建新世界</button><div class="sidebar-bottom"><span class="sidebar-label">工作台</span><button data-do="export">↓ 导出完整存档</button><button data-do="import">↑ 导入存档</button><button data-do="guide">⌘ CLI & Agent 接入</button><div class="local-note"><i class="dot green"></i> 进度仅保存在当前浏览器</div></div></aside><main class="workspace-main"><div class="world-heading"><div><div class="eyebrow">${esc(w.scenario.genre)} <span>/</span> ${historyIndex===null?'LIVE WORLD':'HISTORY'}</div><h1>${esc(w.scenario.title)}</h1><p>${esc(w.scenario.theme)}</p></div><div class="world-controls"><span class="round-badge">${w.scenario.timeLabel} <b>${String(w.round*w.scenario.timeStep).padStart(2,'0')}</b><small>第 ${w.round}/${w.scenario.maxRounds} 轮</small></span><button class="secondary" data-do="auto" ${(!auto&&busy)||w.result||historyIndex!==null?'disabled':''}>${auto?'Ⅱ 暂停':'▷ 自动运行'}</button><button class="primary" data-do="step" ${busy||w.result||historyIndex!==null?'disabled':''}>${busy?'角色正在决策…':'下一轮 →'}</button></div></div>${historyIndex!==null?`<div class="history-banner">正在回看第 ${w.round} 轮，实时世界没有改变。<button data-do="live">返回当前世界</button><button data-do="fork" ${w.round>=w.scenario.maxRounds?'disabled':''}>从这里分支 ↗</button></div>`:''}${w.result?`<div class="outcome ${w.result.success?'success':''}"><b>${w.result.success?'◆ 阶段目标达成':'◆ 本局结束'}</b><span>${esc(w.result.text)}</span></div>`:''}${storyPanel(w)}<div class="metrics">${w.scenario.metrics.map(m=>`<div class="metric"><span>${esc(m.label)}</span><strong>${w.metrics[m.id]}<small>${esc(m.unit)}</small></strong><div class="meter"><i style="width:${(w.metrics[m.id]-m.min)/(m.max-m.min)*100}%;background:${w.metrics[m.id]<25?'#b75f48':w.scenario.accent}"></i></div><small>${m.drift?`每轮 ${m.drift>0?'+':''}${m.drift}`:'随行动变化'}</small></div>`).join('')}</div><div class="simulation-grid"><section class="world-column"><div class="panel">${graph(w)}${actorPanel(w)}</div><section class="intervention panel"><div class="section-heading"><h2>改变故事的走向</h2><span>你的介入，将成为下一轮的起点</span></div><div class="event-chips">${w.scenario.events.map((e,i)=>`<button data-event="${i}" ${busy||w.result||historyIndex!==null?'disabled':''}>＋ ${esc(e.title)}</button>`).join('')}</div><form id="inject-form"><input id="event-input" aria-label="加入剧情事件" placeholder="例如：一封匿名邮件揭露了新的秘密…" maxlength="4000" ${busy||w.result||historyIndex!==null?'disabled':''}><button aria-label="加入事件" class="primary" ${busy||w.result||historyIndex!==null?'disabled':''}>↗</button></form><small>自由文本改变角色可见背景；资源变化可在确认时明确设置。</small></section></section><section class="timeline panel"><div class="timeline-top"><div><h2>世界动态 <span class="live-dot"></span></h2><span>${visibleEvents(w).length} 条记录</span></div><select id="perspective" aria-label="观察视角"><option value="director" ${view==='director'?'selected':''}>导演视角 · 全部可见</option>${w.actors.map(a=>`<option value="${a.id}" ${view===a.id?'selected':''}>${esc(a.name)}的视角</option>`).join('')}</select></div><div class="timeline-tabs"><button class="${tab==='world'?'active':''}" data-tab="world">全部动态</button><button class="${tab==='actions'?'active':''}" data-tab="actions">行动与后果</button></div><div class="events">${eventsHtml(w)}</div></section></div><section class="replay-bar"><span>◷ 时间回放</span><input id="history-slider" aria-label="选择历史节点" type="range" min="0" max="${world.snapshots.length-1}" value="${historyIndex??world.snapshots.length-1}"><span>${historyIndex===null?'当前':`节点 ${historyIndex+1}`} / ${world.snapshots.length}</span><button class="text-button" data-do="live">回到现在 ↗</button></section></main></div>`;}
function render(){ $('#app').innerHTML=screen==='home'?home():screen==='setup'?setup():screen==='intro'?intro():workspace();bind();}
function showModal(html){$('#modal').innerHTML=`<button class="modal-close" aria-label="关闭" data-close>×</button>${html}`;if(!$('#modal').open)$('#modal').showModal();$('#modal [data-close]').onclick=()=>$('#modal').close();}
function settings(){showModal(`<div class="eyebrow">MODEL CONNECTION</div><h2>连接你的模型</h2><p>规则演示无需配置。连接模型后，一句话创建和角色决策将由 AI 驱动。</p><form id="settings-form"><label>API Base URL<input name="base" type="url" value="${esc(config?.baseUrl||'https://api.openai.com/v1')}" required></label><label>模型名称<input name="model" value="${esc(config?.model||'')}" placeholder="填写服务商提供的模型 ID" required></label><label>API Key<input name="key" type="password" value="" autocomplete="off" placeholder="仅在当前页面内存中使用" required></label><p class="small-note">直连模式会把场景与角色上下文发送给你指定的服务商。密钥不保存、不进入存档；服务商需支持浏览器跨域请求。本地可用 .env 服务端代理。</p><button class="primary">保存连接</button><button type="button" class="secondary" id="demo-mode">使用规则演示</button>${serverConfig?.configured?'<button type="button" class="secondary" id="server-mode">使用本地服务端模型</button>':''}</form>`);$('#settings-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);const url=new URL(f.get('base'));if(!['https:','http:'].includes(url.protocol))return notify('请输入 HTTP 地址');config={baseUrl:url.href.replace(/\/$/,''),model:f.get('model'),apiKey:f.get('key')};$('#modal').close();notify('连接设置已保存；首次生成时验证模型服务。');render();};$('#demo-mode').onclick=()=>{config=null;$('#modal').close();render();};if($('#server-mode'))$('#server-mode').onclick=()=>{config={proxy:true,model:serverConfig.model};$('#modal').close();render();};}
function actorEditor(id,isDraft=false){if(busy)return notify('请等待本轮完成');stop();const a=(isDraft?draft.actors:world.actors).find(a=>a.id===id);showModal(`<div class="eyebrow">CHARACTER / ${isDraft?'开局设定':'下一轮生效'}</div><h2>编辑角色</h2><form id="actor-form">${[['name','姓名'],['role','身份'],['goal','私人目标'],['personality','性格'],['secret','私密信息']].map(([k,label])=>`<label>${label}<textarea name="${k}" rows="${['name','role'].includes(k)?1:2}" required maxlength="2000">${esc(a[k])}</textarea></label>`).join('')}<button class="primary">保存角色 →</button></form>`);$('#actor-form').onsubmit=e=>{e.preventDefault();const patch=Object.fromEntries(new FormData(e.target));try{if(isDraft)Object.assign(a,patch);else{editActor(world,id,patch);persist();}$('#modal').close();render();}catch(e){notify(e.message);}};}
function syncDraft(){if($('#theme')){draft.theme=$('#theme').value;draft.opening=$('#opening').value;draft.maxRounds=Number($('#max-rounds').value);document.querySelectorAll('[data-metric]').forEach(el=>draft.metrics.find(m=>m.id===el.dataset.metric).value=Number(el.value));}}
async function step(){if(busy||!world||world.result)return;if(world.story&&!world.pending.some(d=>d.actorId==='ceo'))queueAction(world,{actorId:'ceo',action:'wait',speech:'我先观察这一轮的结果，再决定下一步。',visibility:'public'});busy=true;render();try{const decisions=config?await modelDecisions(world,config):undefined;advance(world,decisions);world.mode=config?'model':'demo';if(world.story?.alert)stop();persist();}catch(e){stop();notify(e.message);}finally{busy=false;render();}if(auto&&!world.result)timer=setTimeout(step,1600);else stop();}
function intervention(data){if(busy||world.result||historyIndex!==null)return;stop();showModal(`<div class="eyebrow">DIRECTOR'S MOVE</div><h2>加入一个事件</h2><form id="event-form"><label>事件标题<input name="title" value="${esc(data.title)}" required maxlength="100"></label><label>发生了什么<textarea name="text" required rows="3">${esc(data.text)}</textarea></label><p class="small-note">确认对当前资源的直接影响。其余后果由接下来的行动产生。</p><div class="resource-inputs">${world.scenario.metrics.map(m=>`<label>${esc(m.label)}变化<input type="number" name="effect-${m.id}" value="${data.effects?.[m.id]??0}" min="${m.min-m.max}" max="${m.max-m.min}"></label>`).join('')}</div><button class="primary">确认加入 →</button></form>`);$('#event-form').onsubmit=e=>{e.preventDefault();try{const f=new FormData(e.target);inject(world,{title:f.get('title'),text:f.get('text'),effects:Object.fromEntries(world.scenario.metrics.map(m=>[m.id,Number(f.get('effect-'+m.id))]))});persist();$('#modal').close();render();}catch(e){notify(e.message);}};}
function control(id){if(busy)return;stop();const a=world.actors.find(a=>a.id===id);showModal(`<div class="eyebrow">TAKE A SEAT</div><h2>接管 ${esc(a.name)}</h2><p>你的发言与行动会替代该角色下一轮的自动决策。</p><form id="control-form"><label>你想说什么<textarea name="speech" required maxlength="1500" rows="3"></textarea></label><label>发给谁<select name="target"><option value="">公开发言</option>${world.actors.filter(x=>x.id!==id).map(x=>`<option value="${x.id}">${esc(x.name)} · 私信</option>`).join('')}</select></label><label>提交行动<select name="action"><option value="wait">等待 / 只发言</option>${world.scenario.actions.map(x=>`<option value="${x.id}">${esc(x.label)}${availability(world,x)?`（${esc(availability(world,x))}）`:''}</option>`).join('')}</select></label><button class="primary">提交至下一轮 →</button></form>`);$('#control-form').onsubmit=e=>{e.preventDefault();try{const f=new FormData(e.target);queueAction(world,{actorId:id,speech:f.get('speech'),target:f.get('target')||undefined,action:f.get('action'),visibility:f.get('target')?'private':'public'});persist();$('#modal').close();notify('行动已排入下一轮');render();}catch(e){notify(e.message);}};}
function download(data,name){const u=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function guide(){showModal(`<div class="eyebrow">WORLDPLAY / v0.1</div><h2>让你的 Agent 进入世界</h2><p>网页与 CLI 使用同一套场景和裁定引擎。先选择默认场景，或连接模型创建自己的世界。</p><ol><li>点击角色，查看目标与私密信息。</li><li>推进一轮，观察行动与资源变化。</li><li>加入事件，或接管角色提交行动。</li><li>拖动时间轴回看，从历史节点创建分支。</li></ol><h3>本地项目命令</h3><pre>npm start\nnode bin/worldplay.mjs init startup\nnode bin/worldplay.mjs observe ceo\nnode bin/worldplay.mjs step\nnode bin/worldplay.mjs export</pre><p class="small-note">CLI 源码位于本地项目，尚未发布 npm 包。配套 Skill 位于 skills/worldplay/SKILL.md。规则演示不调用 AI；接入模型后才会基于角色人格与新增剧情生成决策。关系分当前仅表示通信积累，不是心理预测。完整存档包含角色秘密。</p>`);}
function bind(){if($('#skip-all-intros'))$('#skip-all-intros').onchange=e=>{try{localStorage.setItem('worldplay-skip-intros',e.target.checked?'yes':'no');}catch{notify('无法保存偏好，本次可在故事中跳过全部引导。');}};document.querySelectorAll('[data-talk]').forEach(b=>b.onclick=()=>conversation(b.dataset.talk));document.querySelectorAll('[data-accept]').forEach(b=>b.onclick=()=>{try{negotiate(world,b.dataset.accept,true);persist();$('#modal').close();render();}catch(e){notify(e.message);}});document.querySelectorAll('[data-revisit]').forEach(b=>b.onclick=()=>{stop();historyIndex=Number(b.dataset.revisit);render();});document.querySelectorAll('[data-scenario]').forEach(b=>b.onclick=()=>{if(busy)return;stop();selected=b.dataset.scenario;draft=clone(scenarios.find(s=>s.id===selected));introIndex=0;historyIndex=null;if(skipIntros())enterDemo();else{screen='intro';render();}window.scrollTo(0,0);});document.querySelectorAll('[data-actor]').forEach(b=>b.onclick=()=>{actorId=b.dataset.actor;render();});document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>actorEditor(b.dataset.edit));document.querySelectorAll('[data-edit-draft]').forEach(b=>b.onclick=()=>{syncDraft();actorEditor(b.dataset.editDraft,true);});document.querySelectorAll('[data-control]').forEach(b=>b.onclick=()=>control(b.dataset.control));document.querySelectorAll('[data-event]').forEach(b=>b.onclick=()=>intervention(world.scenario.events[Number(b.dataset.event)]));document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render();});document.querySelectorAll('[data-do]').forEach(b=>b.onclick=()=>dispatch(b.dataset.do));
 if($('#create-form'))$('#create-form').onsubmit=async e=>{e.preventDefault();const text=$('#world-prompt').value.trim();if(!text)return notify('描述一个你想探索的局面');if(!config){notify('自由生成需要连接模型；三个默认世界可直接试玩。');settings();return;}busy=true;render();try{draft=await generateScenario(text,config);screen='setup';}catch(e){notify(e.message);}finally{busy=false;render();}};
 if($('#inject-form'))$('#inject-form').onsubmit=e=>{e.preventDefault();const t=$('#event-input').value.trim();if(t)intervention({title:t.slice(0,40),text:t,effects:{}});};
 if($('#perspective'))$('#perspective').onchange=e=>{view=e.target.value;actorId=view==='director'?actorId:view;render();};
 if($('#history-slider'))$('#history-slider').oninput=e=>{if(busy)return;stop();historyIndex=Number(e.target.value);render();};}
async function dispatch(action){if(busy&&action==='auto'&&auto){stop();render();return;}if(busy&&!['guide'].includes(action))return notify('请等待当前决策完成');switch(action){case'intro-next':introIndex++;if(introIndex>=3)enterDemo();else render();break;case'intro-skip':enterDemo();break;case'intro-edit':screen='setup';render();break;case'play':stop();draft=clone(scenarios.find(s=>s.id==='startup'));world=createWorld(draft,config?'model':'demo');view='ceo';actorId='ceo';historyIndex=null;screen='world';persist();render();break;case'home':stop();screen='home';render();break;case'settings':stop();settings();break;case'guide':guide();break;case'resume':screen='world';historyIndex=null;actorId=world.actors[0].id;render();break;case'start':try{syncDraft();world=createWorld(draft,config?'model':'demo');actorId=world.actors[0].id;view='director';historyIndex=null;screen='world';persist();render();if(world.story){view='ceo';render();break;}const startRound=world.round;await step();if(world.round>startRound&&!world.result)await step();if(world.round>=2)notify('已演化两轮，你可以开始介入。');}catch(e){notify(e.message);}break;case'step':stop();await step();break;case'auto':if(auto){stop();render();}else{auto=true;await step();}break;case'export':download(world,`worldplay-${world.scenario.id}-r${world.round}.json`);break;case'import':{stop();const input=document.createElement('input');input.type='file';input.accept='.json';input.onchange=async()=>{try{if(input.files[0].size>15000000)throw new Error('存档过大');world=importWorld(JSON.parse(await input.files[0].text()));screen='world';actorId=world.actors[0].id;view='director';historyIndex=null;persist();render();}catch(e){notify('无法导入：'+e.message);}};input.click();break;}case'live':historyIndex=null;render();break;case'fork':try{const original=clone(world);const branch=forkWorld(world,historyIndex);download(original,`worldplay-${world.scenario.id}-original.json`);world=branch;historyIndex=null;persist();render();notify('分支已创建，原局已导出保留。');}catch(e){notify(e.message);}break;case'json':syncDraft();showModal(`<h2>编辑世界开局</h2><p>角色、状态、规则均使用同一种场景格式。保存时会检查引用与数值范围。</p><form id="json-form"><textarea class="json-editor" id="json-input" spellcheck="false">${esc(JSON.stringify(draft,null,2))}</textarea><button class="primary">校验并保存 →</button></form>`);$('#json-form').onsubmit=e=>{e.preventDefault();try{draft=validateScenario(JSON.parse($('#json-input').value));$('#modal').close();render();}catch(e){notify(e.message);}};break;}}
render();
fetch('/api/status').then(r=>r.ok?r.json():null).then(s=>{serverConfig=s;if(s?.configured){config={proxy:true,model:s.model};render();}}).catch(()=>{});
// Optional WebMCP bridge: explicit reads and one-round mutation use the same engine/UI.
if(document.modelContext?.registerTool){for(const tool of [{name:'worldplay_observe',description:'Read one character observation in the current world; excludes other roles secrets.',inputSchema:{type:'object',properties:{actorId:{type:'string'}},required:['actorId'],additionalProperties:false},annotations:{readOnlyHint:true},execute:({actorId})=>{if(!world)throw new Error('No world loaded');return observe(world,actorId);}},{name:'worldplay_advance_one_round',description:'Advance the currently loaded world by one round and update the visible UI.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute:async()=>{if(!world||busy||historyIndex!==null||world.result)throw new Error('World cannot advance');await dispatch('step');return {round:world.round,result:world.result};}}]){try{Promise.resolve(document.modelContext.registerTool(tool)).catch(()=>{});}catch{}}}

function storyPanel(w){if(!w.story)return '';const locked=busy||w.result||historyIndex!==null;return `<section class="story-panel"><div class="section-heading"><div><div class="eyebrow">你的身份 · 创始人 / CEO</div><h2>${w.result?'这一次，你留下了什么？':w.story.alert||'承诺之后，才是困难的开始。'}</h2></div>${!locked?'<button class="primary" data-control="ceo">作出本轮决策 →</button>':''}</div><div class="deal-grid">${offers.map(o=>{const a=w.actors.find(a=>a.id===o.actor),d=w.story.deals.find(d=>d.id===o.id);return `<article class="deal-card"><span class="eyebrow">${esc(a?.name)} · ${esc(a?.role)}</span><h3>${esc(o.title)}</h3><p>${esc(o.promise)}</p><strong>${d?({pending:'待兑现',fulfilled:'已兑现',broken:'已失约',unresolved:'本局结束 · 未到期'}[d.status]):w.round>=o.due?'谈判窗口已关闭':`还剩 ${o.due-w.round} 轮`}</strong><button class="secondary" data-talk="${o.id}" ${locked?'disabled':''}>${d?'查看交易':'私聊，了解条件'} ↗</button></article>`;}).join('')}</div><p class="small-note">预设剧情与交易按明确规则结算。自由发言不会自动成为交易；点击接受后才会记入承诺。</p>${w.result?`<div class="story-recap"><h3>关键转折 · 来自本局记录</h3>${w.events.filter(e=>['deal','promise','crisis'].includes(e.type)).map(e=>`<p><b>第 ${e.round} 轮</b> ${esc(e.title)}：${esc(e.text)}</p>`).join('')||'<p>你没有签下任何额外交易。</p>'}<button class="secondary" data-revisit="0">回到开局，尝试另一种选择 ↗</button></div>`:''}</section>`;}
function conversation(id){if(busy||world.result||historyIndex!==null)return;stop();try{negotiate(world,id);persist();const o=offers.find(x=>x.id===id),a=world.actors.find(x=>x.id===o.actor),d=world.story.deals.find(x=>x.id===id);showModal(`<div class="eyebrow">私聊 · 仅你与${esc(a.name)}可见</div><h2>${esc(a.name)}</h2><blockquote>${esc(o.line)}</blockquote><p><b>接受后：</b>${Object.entries(o.up).map(([k,v])=>`${esc(world.scenario.metrics.find(m=>m.id===k).label)} ${v>0?'+':''}${v}`).join('，')}</p><p><b>到期条件：</b>${esc(o.promise)}</p><p><b>兑现：</b>${esc(o.success)}</p><p><b>失约：</b>${esc(o.failure)}</p>${!d&&world.round<o.due?`<button class="primary" id="accept-offer">接受条件，记下承诺 →</button>`:'<p>这项交易已经接受或谈判窗口已关闭。</p>'}<p class="small-note">这是预设谈判。你也可以通过“作出本轮决策”发送自由私信，接入模型后由角色在下一轮回应。</p>`);if($('#accept-offer'))$('#accept-offer').onclick=()=>{try{negotiate(world,id,true);persist();$('#modal').close();render();}catch(e){notify(e.message);}};}catch(e){notify(e.message);}}

function skipIntros(){try{return localStorage.getItem('worldplay-skip-intros')==='yes';}catch{return false;}}
function enterDemo(){stop();world=createWorld(draft,config?'model':'demo');actorId=world.actors[0].id;view=actorId;historyIndex=null;screen='world';persist();render();}
function intro(){const s=draft;const steps=[{label:'故事开场',title:s.title,text:s.opening},{label:'你的角色',title:`你是${s.actors[0].name}`,text:`${s.actors[0].role}。你的目标：${s.actors[0].goal}。你可以私聊其他角色，也可以接管行动。`},{label:'第一次行动',title:s.id==='startup'?'先听听他们的条件':'你准备先做什么？',text:s.id==='startup'?'技术负责人想要交付保障，商业负责人想缩小订单范围，投资人愿意用资金换条件。进入后，选择一个人私聊，再决定是否承诺。':'进入后选择角色，点击“接管本轮行动”提交你的决定。推进下一轮时，其他角色也会行动，世界会结算后果。'}];const step=steps[introIndex];return `${header()}<main class="intro-page"><div class="intro-top"><button class="back" data-do="home">← 返回故事列表</button><button class="quiet" data-do="intro-skip">跳过全部引导 →</button></div><div class="eyebrow">${esc(s.genre)} / ${introIndex+1} OF 3</div><div class="intro-progress">${steps.map((_,i)=>`<span class="${i<=introIndex?'active':''}"></span>`).join('')}</div><span class="field-label">${step.label}</span><h1>${esc(step.title)}</h1><p class="intro-copy">${esc(step.text)}</p><div class="intro-actions"><button class="primary" data-do="intro-next">${introIndex===2?'进入故事 →':'继续 →'}</button><button class="quiet" data-do="intro-next">跳过这一步</button></div><button class="text-button" data-do="intro-edit">先修改角色与世界设定 ↗</button><p class="small-note">跳过只省略引导，不推进时间，也不会替你作出决定。</p></main>${footer()}`;}
